from PIL import Image
import math, statistics
img = Image.open('/app/chess_board.png').convert('RGB')
W,H=img.size
sq=W//8
# compute board colors
means=[[None]*8 for _ in range(8)]
for r in range(8):
    for c in range(8):
        crop=img.crop((c*sq, r*sq, (c+1)*sq, (r+1)*sq))
        pixels=list(crop.getdata())
        mean=[sum(p[i] for p in pixels)/len(pixels) for i in range(3)]
        means[r][c]=mean
board_color={}
for p in [0,1]:
    samples=[means[r][c] for r in range(8) for c in range(8) if (r+c)%2==p]
    board_color[p]=[statistics.median([s[i] for s in samples]) for i in range(3)]

threshold=40

def square_mask(r,c):
    x0,y0=c*sq,r*sq
    crop=img.crop((x0,y0,x0+sq,y0+sq))
    base=board_color[(r+c)%2]
    mask=[[False]*sq for _ in range(sq)]
    for y in range(sq):
        for x in range(sq):
            p=crop.getpixel((x,y))
            d=math.sqrt(sum((p[i]-base[i])**2 for i in range(3)))
            if d>threshold:
                mask[y][x]=True
    return mask

# identify piece squares by pixel count
piece_squares=[]
for r in range(8):
    for c in range(8):
        mask=square_mask(r,c)
        count=sum(sum(1 for v in row if v) for row in mask)
        if count>300:
            piece_squares.append((r,c,count))

# sort
piece_squares=sorted(piece_squares)
print('piece squares',piece_squares)

# function to downsample mask to ascii

def mask_to_ascii(mask, size=16):
    h=len(mask); w=len(mask[0])
    # downsample by averaging blocks
    sx=w//size; sy=h//size
    rows=[]
    for j in range(size):
        row=''
        for i in range(size):
            cnt=0
            for y in range(j*sy,(j+1)*sy):
                for x in range(i*sx,(i+1)*sx):
                    if mask[y][x]: cnt+=1
            row+='#' if cnt> (sx*sy*0.2) else '.'
        rows.append(row)
    return '\n'.join(rows)

for r,c,count in piece_squares:
    print('\nSquare',r,c,'count',count)
    mask=square_mask(r,c)
    print(mask_to_ascii(mask, size=12))
